// HasPrRecord applies the HasEdge predicate on the "pr_record" edge.
func HasPrRecord() predicate.PRCommitUsageSnapshot {
	return predicate.PRCommitUsageSnapshot(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, PrRecordTable, PrRecordColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasPrRecordWith applies the HasEdge predicate on the "pr_record" edge with a given conditions (other predicates).
func HasPrRecordWith(preds ...predicate.PrRecord) predicate.PRCommitUsageSnapshot {
	return predicate.PRCommitUsageSnapshot(func(s *sql.Selector) {
		step := newPrRecordStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

